    demands = get_dict("demands", "demand")
    if demands is None:
        demands = {}
    coords = get_dict("coords", "coordinates", "locations", "xy")
    dm = get_dict("distance_matrix", "distances")

    def node_ids():
        ids = []
        if type(instance) is dict:
            for k in ("customers", "nodes"):
                if k in instance:
                    v = instance[k]
                    if type(v) is dict:
                        for x in v:
                            if x != depot:
                                ids.append(x)
                        return ids
                    for x in v:
                        if x != depot:
                            ids.append(x)
                    return ids
        if type(demands) is dict and demands:
            for x in demands:
                if x != depot:
                    ids.append(x)
            return ids
        if type(dm) is list:
            for i in range(len(dm)):
                if i != depot:
                    ids.append(i)
            return ids
        if type(dm) is dict and dm:
            seen = {}
            for a in dm:
                if a != depot:
                    seen[a] = 1
                row = dm[a]
                if type(row) is dict:
                    for b in row:
                        if b != depot:
                            seen[b] = 1
            return sorted(seen.keys())
        return ids

    customers = node_ids()

    def coord(i):
        if coords is None:
            return None
        if type(coords) is dict:
            v = coords.get(i)
        else:
            if type(i) is int and 0 <= i < len(coords):
                v = coords[i]
            else:
                v = None
        if type(v) is dict and "x" in v and "y" in v:
            return (v["x"], v["y"])
        return v

    def dist(a, b):
        if a == b:
            return 0
        if type(dm) is list:
            try:
                return dm[a][b]
            except:
                pass
        elif type(dm) is dict:
            row = dm.get(a)
            if type(row) is dict and b in row:
                return row[b]
        ca = coord(a)
        cb = coord(b)
        if ca is not None and cb is not None:
            ax = ca[0]
            ay = ca[1]
            bx = cb[0]
            by = cb[1]
            return ((ax - bx) * (ax - bx) + (ay - by) * (ay - by)) ** 0.5
        if type(a) is int and type(b) is int:
            return abs(a - b)
        return 1

    def dem(i):
        if type(demands) is dict:
            return demands.get(i, 0)
        if type(demands) is list and type(i) is int and 0 <= i < len(demands):
            return demands[i]
        return 0

    def route_demand(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    def route_cost(r):
        if not r:
            return 0
        c = dist(depot, r[0]) + dist(r[-1], depot)
        for i in range(len(r) - 1):
            c += dist(r[i], r[i + 1])
        return c

    def best_insert_pos(route, c):
        if not route:
            return dist(depot, c) + dist(c, depot), 0
        best = dist(depot, c) + dist(c, depot)
        pos = 0
        x = dist(depot, c) + dist(c, route[0]) - dist(depot, route[0])
        if x < best:
            best = x
            pos = 0
        for i in range(len(route) - 1):
            x = dist(route[i], c) + dist(c, route[i + 1]) - dist(route[i], route[i + 1])
            if x < best:
                best = x
                pos = i + 1
        x = dist(route[-1], c) + dist(c, depot) - dist(route[-1], depot)
        if x < best:
            best = x
            pos = len(route)
        return best, pos

    def two_opt(route):
        n = len(route)
        if n < 4:
            return route
        improved = True
        while improved:
            improved = False
            base = route_cost(route)
            best_gain = 0
            bi = -1
            bj = -1
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = route[:i + 1] + route[i + 1:j + 1][::-1] + route[j + 1:]
                    gain = base - route_cost(cand)
                    if gain > best_gain:
                        best_gain = gain
                        bi = i
                        bj = j
            if best_gain > 0:
                route = route[:bi + 1] + route[bi + 1:bj + 1][::-1] + route[bj + 1:]
                improved = True
        return route

    if not customers:
        return []

    unassigned = {}
    for c in customers:
        unassigned[c] = 1

    routes = []

    while unassigned:
        seed = None
        seed_key = None
        for c in unassigned:
            key = (-dem(c), -dist(depot, c), c)
            if seed is None or key < seed_key:
                seed = c
                seed_key = key
        route = [seed]
        load = dem(seed)
        del unassigned[seed]

        while True:
            best_c = None
            best_pos = 0
            best_key = None
            for c in unassigned:
                d = dem(c)
                if load + d > capacity:
                    continue
                gain, pos = best_insert_pos(route, c)
                key = (gain, dist(depot, c), c)
                if best_c is None or key < best_key:
                    best_c = c
                    best_pos = pos
                    best_key = key
            if best_c is None:
                break
            route = route[:best_pos] + [best_c] + route[best_pos:]
            load += dem(best_c)
            del unassigned[best_c]

        route = two_opt(route)
        routes.append(route)

    if len(routes) > 1:
        improved = True
        while improved:
            improved = False
            for i in range(len(routes)):
                for j in range(len(routes)):
                    if i == j or not routes[i] or not routes[j]:
                        continue
                    a = routes[i]
                    b = routes[j]
                    changed = False
                    for idx in range(len(a)):
                        c = a[idx]
                        dc = dem(c)
                        if route_demand(b) + dc > capacity:
                            continue
                        best_gain_b, pos_b = best_insert_pos(b, c)
                        old_cost = route_cost(a) + route_cost(b)
                        na = a[:idx] + a[idx + 1:]
                        nb = b[:pos_b] + [c] + b[pos_b:]
                        if na and route_cost(na) + route_cost(nb) < old_cost:
                            routes[i] = na
                            routes[j] = two_opt(nb)
                            improved = True
                            changed = True
                            break
                    if changed:
                        break
                if improved:
                    break

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = 1
    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)

    for c in missing:
        best_r = None
        best_pos = 0
        best_key = None
        for ridx in range(len(routes)):
            r = routes[ridx]
            if route_demand(r) + dem(c) > capacity:
                continue
            gain, pos = best_insert_pos(r, c)
            key = (gain, ridx, pos)
            if best_r is None or key < best_key:
                best_r = ridx
                best_pos = pos
                best_key = key
        if best_r is None:
            routes.append([c])
        else:
            r = routes[best_r]
            routes[best_r] = r[:best_pos] + [c] + r[best_pos:]

    final_routes = []
    for r in routes:
        if r:
            final_routes.append(r)
    return final_routes
